import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"离下离上 离：","description":"京氏易传 - 离下离上 离：","frontmatter":{"title":"离下离上 离：","description":"京氏易传 - 离下离上 离："},"headers":[],"relativePath":"zh/classics/jingshi/050.md","filePath":"zh/classics/jingshi/050.md"}'),i={name:"zh/classics/jingshi/050.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"离下离上-离",tabindex:"-1"},[l("离下离上 离： "),e("a",{class:"header-anchor",href:"#离下离上-离","aria-label":"Permalink to “离下离上 离：”"},"​")],-1),e("p",null,"本于纯阳，阴气贯中，禀于刚健，见乎文明。故《易》曰：“君子以继明照于四方”。（虎易注：此句出于象辞，原句为：“象曰：明两作，离，大人以继明照于四方。”其中的“君子”当为“大人”之误。）【离卦中虚，始于乾象。纯则健，不能柔明，故以北方阴气贯中，柔刚而文明也。】阳为阴主，阳伏于阴也。【成卦义在六五。】是以体离，为日为火，始于阳象而假以阴气。纯用刚健，不能明照，故以阴气入阳，柔于刚健而能顺柔，中虚见火象也。【是以离取中虚，气炎方能照物，日昌火，本阳象也。纯以阴，又不能乾于物，纯以阳，又暴于物，故取阴柔于中女，能成于物也。】与坎为飞伏。【己巳火，戊子土。】（虎易注：戊子土当为戊子水之误。）宗庙为世，应上见三公。【上九，九三。】",-1),e("p",null,"建始戊申至癸丑，【立秋至大寒。】积算起癸丑至壬子，【火取胎月至本月。】周而复始。土水二象入离火位，【土水二位入卦起算。】",-1),e("p",null,"五星从位起岁星，【木星入火宫卦。】室宿从位降己巳火，【二十八宿，分室宿入离宫上九己巳火上也。】分气候三十六。【积算起数三十六，立位定吉凶。】",-1),e("p",null,"内外二象，配于火土为祥。【土火入离为祥。】互见悦顺，著于明丽。【兑巽二象。】",-1),e("p",null,"阴阳升降入初九，适变从阴，止于艮象。【内卦变也。】吉凶从位，起至六五，休废在何爻。【看当何位金水木火土，与本宫刑宫。】次降入火山旅卦。【初九爻变之。】",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
